import { useState, useRef } from 'react';

export function SplitPane() {
  const [w, setW] = useState(50);
  const dragging = useRef(false);
  return (
    <div className="flex h-screen select-none" onMouseMove={(e) => {
      if (!dragging.current) return;
      setW((e.clientX / window.innerWidth) * 100);
    }} onMouseUp={() => (dragging.current = false)}>
      <div style={{ width: `${w}%` }} className="overflow-auto border-r p-4">{{left_content}}</div>
      <div onMouseDown={() => (dragging.current = true)} className="w-1 cursor-col-resize bg-gray-200 hover:bg-blue-500" />
      <div className="flex-1 overflow-auto p-4">{{right_content}}</div>
    </div>
  );
}
